// Precision-aware View (task T0030, docs/P_MIXED_PRECISION.md), generated by
// bots/p_only/tools/derive/make_families.py. Do not edit. Included instead of the plain view only when a family
// carrier is built with PONLY_PRECISION=1. View::profile (Reference16 unless a carrier routes otherwise) selects
// the precision of every head of one build; the bank dispatches it (inference/policy_precision/bank.hpp), and a
// missing or other-family low-bit model falls back to the INT16 model (View::used says what ran).
// Generated by bots/p_only/tools/derive/make_families.py from ponly.hpp. Do not edit.
// Policy family p3: the same View with PolicyFeaturesP3 and PolicyModelP3
// (inference/policy_p3.hpp). One combat summary per built state serves every
// encoded team; `rules` (damage and hit points from INIT) must be set by the
// carrier before the first build. The p2 part of every input is the legacy
// encoder's, bit for bit.
// P-only opponent model: the single source of every prediction a P-only
// carrier makes about what opponents will do.
//
// A View holds the policy network's predictions for one decision state, the
// real root or a simulated branch state:
//
//   movement   the 125-way joint per opponent team and its unit marginals;
//   actions    P(wait, pickup, drop, attack | unit, move);
//   targets    P(candidate c | unit attacks after move), over the encoder's
//              attack candidates (enemy unit ids, nearest first).
//
// There is no legacy forecast, no mixture weight and no hand-written fallback:
// without a model (or for a team that was not encoded) every distribution is
// uniform over what the rules allow, and `Counters::fallback` counts it. Game
// rules (legal moves, which actions take effect, attack range and line of
// fire, settlement) stay with the carrier; this header only predicts choices.
//
// History: build() takes the state and its parent. A carrier passes the
// previous real observation at the root and the root state for a branch, and
// never lets a branch replace the root's history (see each carrier's PSession).
//
// Randomness is a deterministic hash of integer keys, so the same keys give
// the same draws (common random numbers across candidate plans).
#ifndef PONLY_P3_HPP
#define PONLY_P3_HPP
#include <array>
#include <cstdint>
#include <vector>

#include "adapter.hpp"
#include "features.hpp"
#include "policy.hpp"
#include "policy_precision/bank.hpp"
#include "policy_p3.hpp"
#include "state.hpp"

#ifndef PONLY_PRECISION_REGISTER
#define PONLY_PRECISION_REGISTER(bank) ((void)0)  // a variant registers its low-bit models
#endif
namespace ponly {

// The low-bit models of the running model set, by legacy model type (none unless a variant registers them).
template <class M>
inline fusion::precision::PolicyBank<M>& precisionBank() {
    static fusion::precision::PolicyBank<M> bank = [] { fusion::precision::PolicyBank<M> b; PONLY_PRECISION_REGISTER(b); return b; }();
    return bank;
}
// The bank for this build's INT16 model (its Reference16 entry).
template <class M>
inline const fusion::precision::PolicyBank<M>& bankFor(const M* model) {
    auto& b = precisionBank<M>();
    b.reference16 = model;
    return b;
}

inline constexpr int kMoves = fusion::kMoves;
inline constexpr int kActs = fusion::kActs;
inline constexpr int kCand = fusion::kCand;

// Uniform in [0, 1) from integer keys.
inline double uniform(uint32_t a, uint32_t b, uint32_t c, uint32_t d = 0) {
    uint32_t h = a * 0x9e3779b1U ^ (b + 0x7f4a7c15U) * 0x85ebca6bU ^ (c + 0x165667b1U) * 0xc2b2ae35U ^ (d + 0x27d4eb2fU) * 0x94d049bbU;
    h ^= h >> 16; h *= 0x7feb352dU; h ^= h >> 15; h *= 0x846ca68bU; h ^= h >> 16;
    return (h >> 8) * (1.0 / 16777216.0);
}

struct Counters {
    long long builds = 0, teams = 0, actHeads = 0, targetHeads = 0, fallback = 0;
    long long branches = 0;      // simulated states a carrier predicted (incremented by the carrier)
    long long inconsistent = 0;  // states that break the rules' invariants, or contradict the carrier's search
    long long skipped = 0;       // simulated states with a pending random flag return (that flag left out)
};

// One unit's order: the move index, the act (fusion::kWait/kPickup/kDrop/kAttack)
// and, for an attack, the target unit id (else -1).
struct Order { int move = 0, act = fusion::kWait, target = -1; };

class View {
public:
    Counters* counters = nullptr;
    fusion::precision::Profile profile = fusion::precision::Profile::Reference16;  // set before build()
    fusion::precision::Profile used = fusion::precision::Profile::Reference16;     // what the last build ran
    fusion::Rules rules{};  // engine damage and hit points (INIT); set by the carrier

    // Encodes `s` for every opponent team of `me` (or only the teams with
    // want[t] != 0) and runs the joint movement head for each active team.
    // `parent` is the previous observation (history features) or nullptr.
    void build(const fusion::Board& b, const fusion::State& s, const fusion::State* parent, int me,
               const fusion::PolicyModelP3* model, const std::vector<char>* want = nullptr) {
        b_ = &b;
        model_ = model;
        me_ = me;
        s_ = s;
        teams_ = b.teams;
        const int U = static_cast<int>(s.units.size());
        fusion::makeView(b, s_, parent, v_);
        fusion::summarize(b, rules, s_, v_, cs_);
        if (counters && !coherent(s_)) counters->inconsistent++;
        has_.assign(teams_, 0);
        feat_.resize(teams_);
        out_.resize(teams_);
        act_.resize(U);
        tgt_.resize(U);
        actDone_.assign(U, {});
        tgtDone_.assign(U, {});
        if (counters) counters->builds++;
        for (int t = 0; t < teams_; t++) {
            if (t == me || (want && !(*want)[t])) continue;
            bool active = false;
            for (int k = 0; k < 3; k++) {
                const int uid = 3 * t + k;
                if (uid < U && v_.origin[uid] >= 0) active = true;
            }
            if (!active) continue;
            fusion::encodePolicyP3(b, s_, v_, cs_, t, feat_[t]);
            if (model_) {
                used = fusion::precision::predictJoint(bankFor(model_), profile, feat_[t], out_[t]);
            } else {
                uniformJoint(feat_[t], out_[t]);
                if (counters) counters->fallback++;
            }
            has_[t] = 1;
            if (counters) counters->teams++;
        }
    }

    const fusion::State& state() const { return s_; }
    const fusion::TurnView& turnView() const { return v_; }
    bool has(int team) const { return team >= 0 && team < (int)has_.size() && has_[team]; }
    int origin(int uid) const { return uid >= 0 && uid < (int)v_.origin.size() ? v_.origin[uid] : -1; }
    bool legal(int uid, int m) const { const int t = uid / 3; return has(t) && feat_[t].legal[uid % 3][m]; }
    // Whether act a has an effect after move m (the network gives the others zero).
    bool actLegal(int uid, int m, int a) const { const int t = uid / 3; return has(t) && feat_[t].actLegal[uid % 3][m][a]; }

    // P(unit uid moves m); 0 for a team without predictions (callers check has()).
    double move(int uid, int m) const {
        const int t = uid / 3, k = uid % 3;
        if (has(t)) return out_[t].marginal[k][m];
        return 0.0;
    }

    // P(act | unit uid makes move m), cached.
    const std::array<double, kActs>& act(int uid, int m) {
        auto& a = act_[uid][m];
        if (actDone_[uid][m]) return a;
        actDone_[uid][m] = 1;
        a.fill(0.0);
        const int t = uid / 3, k = uid % 3;
        if (!has(t) || !feat_[t].legal[k][m]) { a[fusion::kWait] = 1.0; return a; }
        if (model_) {
            fusion::precision::predictAct(bankFor(model_), used, feat_[t], k, m, a.data());
            if (counters) counters->actHeads++;
        } else {
            int n = 0;
            for (int i = 0; i < kActs; i++) n += feat_[t].actLegal[k][m][i] != 0;
            for (int i = 0; i < kActs; i++) a[i] = feat_[t].actLegal[k][m][i] ? 1.0 / n : 0.0;
            if (counters) counters->fallback++;
        }
        return a;
    }

    // P(candidate slot c | unit uid attacks after move m), cached.
    const std::array<double, kCand>& target(int uid, int m) {
        auto& p = tgt_[uid][m];
        if (tgtDone_[uid][m]) return p;
        tgtDone_[uid][m] = 1;
        p.fill(0.0);
        const int t = uid / 3, k = uid % 3;
        if (!has(t) || !feat_[t].legal[k][m]) return p;
        if (model_) {
            fusion::precision::predictTarget(bankFor(model_), used, feat_[t], k, m, p.data());
            if (counters) counters->targetHeads++;
        } else {
            int n = 0;
            for (int c = 0; c < kCand; c++) n += feat_[t].cand[k][c] >= 0;
            for (int c = 0; c < kCand; c++) p[c] = n && feat_[t].cand[k][c] >= 0 ? 1.0 / n : 0.0;
            if (counters) counters->fallback++;
        }
        return p;
    }

    // Enemy unit id in attack candidate slot c of unit uid (-1 = empty).
    int candidate(int uid, int c) const { const int t = uid / 3; return has(t) ? feat_[t].cand[uid % 3][c] : -1; }

    // True when unit `victim` is one of uid's attack candidates (only then can
    // the network aim at it this turn).
    bool canAim(int uid, int victim) const {
        const int t = uid / 3;
        if (!has(t)) return false;
        for (int c = 0; c < kCand; c++) if (feat_[t].cand[uid % 3][c] == victim) return true;
        return false;
    }

    // P(unit uid attacks | move m).
    double fire(int uid, int m) { return act(uid, m)[fusion::kAttack]; }

    // P(unit uid attacks `victim` | move m) = P(attack | m) * P(target = victim | attack, m).
    double aim(int uid, int m, int victim) {
        if (!canAim(uid, victim)) return 0.0;
        const double f = fire(uid, m);
        if (f <= 0) return 0.0;
        const auto& p = target(uid, m);
        for (int c = 0; c < kCand; c++) if (candidate(uid, c) == victim) return f * p[c];
        return 0.0;
    }

    // Team movement: the most probable joint move, or a draw with uniform u.
    void jointMode(int team, int mv[3]) const {
        mv[0] = mv[1] = mv[2] = 0;
        if (!has(team)) return;
        const auto& pr = out_[team].prob;
        int best = 0;
        for (int j = 1; j < fusion::kJoint; j++) if (pr[j] > pr[best]) best = j;
        mv[0] = best / 25; mv[1] = best / 5 % 5; mv[2] = best % 5;
    }
    void jointDraw(int team, double u, int mv[3]) const {
        mv[0] = mv[1] = mv[2] = 0;
        if (!has(team)) return;
        const int j = fusion::sampleIndex(out_[team].prob.data(), fusion::kJoint, u);
        mv[0] = j / 25; mv[1] = j / 5 % 5; mv[2] = j % 5;
    }

    // The act and target of unit uid after move m: the mode (uAct < 0) or a draw.
    Order order(int uid, int m, double uAct, double uTarget) {
        Order o;
        o.move = m;
        const auto& a = act(uid, m);
        if (uAct < 0) {
            int best = 0;
            for (int i = 1; i < kActs; i++) if (a[i] > a[best]) best = i;
            o.act = best;
        } else {
            o.act = fusion::sampleIndex(a.data(), kActs, uAct);
        }
        if (o.act == fusion::kAttack) {
            const auto& p = target(uid, m);
            int slot = 0;
            if (uTarget < 0) { for (int c = 1; c < kCand; c++) if (p[c] > p[slot]) slot = c; }
            else slot = fusion::sampleIndex(p.data(), kCand, uTarget);
            o.target = candidate(uid, slot);
            if (o.target < 0) o.act = fusion::kWait;
        }
        return o;
    }

    // Orders for the three units of `team`: mode (sample < 0) or the draw keyed
    // by (turn, team, sample, salt).
    std::array<Order, 3> teamOrders(int team, int sample, uint32_t salt) {
        std::array<Order, 3> out{};
        int mv[3];
        if (sample < 0) jointMode(team, mv);
        else jointDraw(team, uniform(s_.turn, team, sample, salt), mv);
        for (int k = 0; k < 3; k++) {
            const int uid = 3 * team + k;
            const double ua = sample < 0 ? -1.0 : uniform(s_.turn, uid, sample, salt + 1);
            const double ut = sample < 0 ? -1.0 : uniform(s_.turn, uid, sample, salt + 2);
            out[k] = origin(uid) >= 0 ? order(uid, mv[k], ua, ut) : Order{};
        }
        return out;
    }

    // The rules' invariants for a state handed to the network: a unit on the
    // board is alive; an off-board unit carries nothing; a carried flag has a
    // living holder that carries it; a home or dropped flag lies on the board.
    static bool coherent(const fusion::State& s) {
        const int U = static_cast<int>(s.units.size()), F = static_cast<int>(s.flags.size());
        for (const auto& u : s.units) {
            if (u.x >= 0 && u.hp <= 0) return false;
            if (u.x < 0 && u.flag >= 0) return false;
            if (u.flag >= F) return false;
            if (u.flag >= 0 && (s.flags[u.flag].status != fusion::kCarried || s.flags[u.flag].holder != u.id)) return false;
        }
        for (const auto& f : s.flags) {
            if (f.status == fusion::kCarried && (f.holder < 0 || f.holder >= U || s.units[f.holder].flag != f.id)) return false;
            if ((f.status == fusion::kHome || f.status == fusion::kDropped) && f.x < 0) return false;
        }
        return true;
    }

private:
    static void uniformJoint(const fusion::PolicyFeatures& f, fusion::PolicyOutput& out) {
        double total = 0;
        for (int j = 0; j < fusion::kJoint; j++) {
            const bool ok = f.legal[0][j / 25] && f.legal[1][j / 5 % 5] && f.legal[2][j % 5];
            out.prob[j] = ok ? 1.0 : 0.0;
            out.logit[j] = ok ? 0.0 : fusion::kNegInf;
            total += out.prob[j];
        }
        for (auto& row : out.marginal) row.fill(0);
        for (int j = 0; j < fusion::kJoint; j++) {
            out.prob[j] = total > 0 ? out.prob[j] / total : 0.0;
            out.marginal[0][j / 25] += out.prob[j];
            out.marginal[1][j / 5 % 5] += out.prob[j];
            out.marginal[2][j % 5] += out.prob[j];
        }
    }

    const fusion::Board* b_ = nullptr;
    const fusion::PolicyModelP3* model_ = nullptr;
    fusion::CombatSummary cs_;
    fusion::State s_;
    fusion::TurnView v_;
    int me_ = -1, teams_ = 0;
    std::vector<char> has_;
    std::vector<fusion::PolicyFeaturesP3> feat_;
    std::vector<fusion::PolicyOutput> out_;
    std::vector<std::array<std::array<double, kActs>, kMoves>> act_;
    std::vector<std::array<std::array<double, kCand>, kMoves>> tgt_;
    std::vector<std::array<unsigned char, kMoves>> actDone_, tgtDone_;
};

// Move index (S, U, D, L, R) that takes cell `from` to cell `to` on an n-wide grid, -1 if not adjacent.
inline int moveIndex(int from, int to, int n) {
    if (from < 0 || to < 0) return -1;
    if (to == from) return 0;
    if (to == from - n) return 1;
    if (to == from + n) return 2;
    if (to == from - 1 && from % n != 0) return 3;
    if (to == from + 1 && to % n != 0) return 4;
    return -1;
}

}  // namespace ponly
#endif  // PONLY_P3_HPP
